          "title": "Verify Trust Boundary Integrity for tb-009: Is the active validator set correctly filtered before proposer selection?",
          "severity": "High",
          "mindset": "Boundary Guard",
          "is_boundary_check": true,
          "reachability": {
            "classification": "internal-only",
            "entry_points": [
              "Internal"
            ],
            "attacker_controlled": false,
            "validation_layers": [],
            "bug_bounty_scope": "in-scope",
            "notes": "If inactive validators are included in the selection pool, they could be chosen as proposers but would be unable to produce blocks."
          },
          "test_procedure": "1. Locate the get_beacon_proposer_indices function in the consensus layer implementation. 2. Verify that get_active_validator_indices(state, epoch) is called before any proposer selection logic. 3. Trace the validator set used in proposer computation and confirm it originates from get_active_validator_indices.",
          "bug_class": "State Consistency",
          "risk_category": "Denial of Service",
          "notes": "Source: PROP-W1B10-38, Invariant: FULU-SG006-INV-001, Trust Boundary: tb-009."
        },
        "code_scope": {
          "locations": [
            {
              "file": "beacon-chain/core/helpers/validators.go",
              "symbol": "ActiveValidatorIndices",
              "line_range": {
                "start": 104,
                "end": 145
              },
              "role": "primary"
            },
            {
              "file": "beacon-chain/core/helpers/beacon_committee.go",
              "symbol": "InitializeProposerLookahead",
              "line_range": {
                "start": 655,
                "end": 672
              },
              "role": "caller"
            },
            {
